Feature: Set auto-play for Video Widgets

  Scenario: User sets auto-play as default for Video Widgets
    Given a Smart Page with a Video Widget
    And the auto-play button is unchecked by default
    When the user checks the auto-play button
    Then the Video Widget should be set to auto-play on viewing

Python:
from behave import given, when, then

@given('a Smart Page with a Video Widget')
def step_given_smart_page_with_video_widget(context):
    context.smart_page = SmartPage()
    context.video_widget = context.smart_page.add_video_widget()

@given('the auto-play button is unchecked by default')
def step_given_auto_play_button_unchecked(context):
    assert not context.video_widget.is_auto_play_enabled()

@when('the user checks the auto-play button')
def step_when_user_checks_auto_play_button(context):
    context.video_widget.set_auto_play(True)

@then('the Video Widget should be set to auto-play on viewing')
def step_then_video_widget_auto_plays(context):
    assert context.video_widget.is_auto_play_enabled()

